<style>.ava-strategy-card{display:grid;gap:1rem;padding:1.2rem;border:1px solid #dce3e8;border-radius:1rem;background:#fff}.ava-environment-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.ava-environment-card,.ava-exclusive-card{margin:0;padding:1rem;border:1px solid #dce3e8;border-radius:.9rem;background:#f8fafb}.ava-environment-card{display:grid;align-content:start;gap:1rem}.ava-exclusive-card>summary{display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:.8rem;cursor:pointer;list-style:none}.ava-exclusive-card>summary::-webkit-details-marker{display:none}.ava-exclusive-card>summary>span{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:.75rem;background:#fff0f1;color:var(--inter-accent)}.ava-exclusive-card h3,.ava-exclusive-card p{margin:0}.ava-exclusive-card[open] .ava-exclusive-chevron{transform:rotate(180deg)}.ava-exclusive-body{display:grid;gap:1rem;margin-top:1rem;padding-top:1rem;border-top:1px solid #dce3e8}.ava-execution-badge{display:inline-flex;align-items:center;gap:.35rem;width:max-content;max-width:100%;margin-top:.45rem;padding:.3rem .55rem;border-radius:999px;background:#e8f1ff;color:#1f5f9f;font-size:.72rem;font-weight:800}.ava-capabilities{display:flex;flex-wrap:wrap;gap:.35rem;grid-column:1/-1}.ava-capabilities span{display:inline-flex;align-items:center;gap:.25rem;padding:.25rem .45rem;border-radius:999px;background:#edf0f2;color:#7b8790;font-size:.7rem;font-weight:700}.ava-capabilities span.is-ready{background:#e4f7ec;color:#0a7a45}.ava-catalog-card{align-content:start}.ava-catalog-copy{min-width:0}@media(max-width:900px){.ava-environment-grid{grid-template-columns:1fr}}@media(max-width:600px){.ava-exclusive-card>summary{grid-template-columns:auto 1fr}.ava-exclusive-card>summary .connection-badge,.ava-exclusive-chevron{grid-column:auto}.ava-execution-badge{white-space:normal}}</style>
<style>.ava-offers-section{min-height:0}.ava-offer-catalogs{display:grid;gap:.8rem}.ava-offer-catalog{border:1px solid #dce3e8;border-radius:.9rem;overflow:hidden;background:#fff}.ava-offer-catalog>summary{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.1rem;cursor:pointer;background:#f8fafb}.ava-offer-catalog>summary>span:first-child{display:grid;grid-template-columns:auto 1fr;column-gap:.65rem;align-items:center}.ava-offer-catalog>summary i{grid-row:1/3;color:var(--inter-accent)}.ava-offer-catalog>summary strong,.ava-offer-catalog>summary small{display:block}.ava-offer-catalog>summary small{color:var(--inter-muted)}.ava-offer-catalog>.alert{margin:.8rem}.ava-offer-list{display:grid}.ava-offer-subheading{display:flex;align-items:center;gap:.55rem;padding:.75rem 1rem;border-top:1px solid #e7ecef;background:#f5f8fa;color:#334155}.ava-offer-subheading span{margin-left:auto;color:var(--inter-muted);font-size:.78rem}.ava-offer-row{display:grid;grid-template-columns:minmax(13rem,.8fr) minmax(0,2.2fr) 2.8rem 2.8rem;gap:.65rem;align-items:start;padding:1rem;border-top:1px solid #e7ecef}.ava-offer-row.is-blocked{background:#fff8f8}.ava-offer-course{display:flex;align-items:center;gap:.7rem;min-width:0}.ava-offer-course img,.ava-offer-course>span{flex:0 0 auto;width:3.4rem;height:2.7rem;object-fit:cover;border-radius:.6rem;background:#fff0f1;color:var(--inter-accent)}.ava-offer-course>span{display:grid;place-items:center}.ava-offer-course strong,.ava-offer-course small{display:block}.ava-offer-course strong{overflow-wrap:anywhere}.ava-offer-course small{margin-top:.2rem;color:var(--inter-muted)}.ava-offer-form{display:grid;grid-template-columns:minmax(12rem,1.4fr) minmax(7rem,.55fr) minmax(5rem,.35fr) auto;gap:.7rem;align-items:end}.ava-offer-form label{display:grid;gap:.3rem;margin:0}.ava-offer-form input,.ava-offer-form textarea{width:100%}.ava-offer-description{grid-column:1/3}.ava-offer-description textarea{min-height:4.2rem}.ava-offer-switches{display:flex;gap:.8rem;align-items:center;grid-column:3/5}.ava-offer-switches label{display:flex;align-items:center;gap:.35rem}.ava-item-access,.ava-offer-delete{display:flex;align-items:center;justify-content:center;margin-top:1.45rem}.ava-item-access .action-icon,.ava-offer-delete .action-icon{display:grid;place-items:center;width:2.8rem;height:2.8rem;margin:0;border:1px solid #d5dfe5;border-radius:.7rem}.ava-item-access .action-icon.is-danger{background:#fff0f1;color:#b91c27;border-color:#f0b5ba}.ava-item-access .action-icon.is-success{background:#e6f7ee;color:#08723d;border-color:#b8e3cc}.ava-offer-delete .action-icon{border:0;background:#bd1f2d;color:#fff}.ava-item-access .action-icon:disabled{opacity:.45;cursor:not-allowed}.ava-catalog-card.is-blocked{border-color:#f0bec2;background:#fff7f7}.ava-catalog-card.is-blocked .ava-catalog-copy{opacity:.72}@media(max-width:1100px){.ava-offer-row{grid-template-columns:1fr auto auto}.ava-offer-course,.ava-offer-form{grid-column:1/-1}.ava-offer-form{grid-template-columns:repeat(2,minmax(0,1fr))}.ava-item-access,.ava-offer-delete{margin:0}.ava-offer-description,.ava-offer-switches{grid-column:1/-1}}@media(max-width:650px){.ava-offer-row{grid-template-columns:1fr auto auto}.ava-offer-form{grid-template-columns:1fr}.ava-offer-description,.ava-offer-switches{grid-column:auto}.ava-offer-switches{align-items:flex-start;flex-direction:column}}</style>
